input_grid = demo['input']
section1 = demo['output'][:8]

# Get counts
from collections import Counter
input_counts = Counter([cell for row in input_grid for cell in row])
section1_counts = Counter([cell for row in section1 for cell in row])

print("Input counts:", input_counts)
print("Section 1 counts:", section1_counts)

# Let me look for specific cells and their corresponding positions
